('hon_l1','honesty','lesson','ما هو الصدق؟','1f60a',array['a2','a3','a4','a5','a6','g1','g2','g3','g4']::text[],1,$j${"goal": "أعرف أن الصدق يعني أن أقول ما حدث فعلا.", "pages": [{"t": "الصدق أن نقول ما حدث فعلا، حتى لو كان الأمر صعبا.", "img": "1f60a", "k": "explain"}, {"t": "عندما نصدق يطمئن إلينا من حولنا ويثقون بنا.", "img": "1f468-1f469-1f467", "k": "explain"}, {"t": "مثال: كسرت سارة كوبا بالخطأ، فأخبرت أمها بما حدث. شكرتها أمها وساعدتها على جمع القطع.", "img": "1f9d2", "k": "example"}], "check": {"q": "ماذا فعلت سارة بعد أن كسرت الكوب؟", "o": ["أخبرت أمها بما حدث", "أخفت القطع", "قالت إن القطة كسرته"], "a": 0, "why": "الصدق أن نقول ما حدث، وهكذا يساعدنا من نحب."}}$j$::jsonb,null,'كُتب النشاط برمجيا بصياغة أصلية مناسبة للعمر، وفُحصت بنيته آليا (الإجابات والخيارات والأحرف والرسوم)، وخلا من العبارات المخيفة أو المحرجة. لم يراجعه مربٍّ متخصص بعد.',true,'published',1),
('hon_s1','honesty','story','مروان والملصق','i_star',array['a3','a4','a5','a6','g1','g2']::text[],1,$j${"pages": [{"t": "وجد مروان ملصقا جميلا على طاولة صديقه سالم، وكان سالم قد ذهب إلى البيت.", "img": "i_star"}, {"t": "أعجب الملصق مروان كثيرا، وفكر أن يضعه في جيبه.", "img": "1f914"}, {"t": "ثم تذكر مروان أن الملصق ليس له.", "img": "1f4a1"}], "dilemma": {"q": "ماذا يفعل مروان؟", "opts": [{"t": "يترك الملصق مكانه ويخبر سالما غدا", "res": "ترك مروان الملصق مكانه، وفي الصباح أخبر سالما. فرح سالم وشكر صديقه على أمانته."}, {"t": "يأخذ الملصق ويسكت", "res": "لو أخذ مروان الملصق لحزن سالم، ولبقي مروان منشغل البال. لنجرب خيارا آخر."}, {"t": "يعطي الملصق لطفل آخر", "res": "الملصق ليس لمروان حتى يعطيه لغيره. الأفضل أن يعود إلى صاحبه."}]}, "quiz": {"q": "لمن كان الملصق؟", "o": ["لسالم", "لمروان", "لطفل لا نعرفه"], "a": 0, "why": "الملصق لسالم، والأمانة أن نعيد الأشياء إلى أصحابها."}, "act": "أعد اليوم شيئا استعرته أو وجدته إلى صاحبه، وقل له شكرا."}$j$::jsonb,'اسألوا طفلكم: كيف شعر مروان عندما ترك الملصق؟ وأثنوا على كل موقف أمين يرويه لكم.','كُتب النشاط برمجيا بصياغة أصلية مناسبة للعمر، وفُحصت بنيته آليا (الإجابات والخيارات والأحرف والرسوم)، وخلا من العبارات المخيفة أو المحرجة. لم يراجعه مربٍّ متخصص بعد.',true,'published',2),
